    "text_blocks": [
      {
        "type": "paragraph",
        "snippet": "You can check your Ayushman Bharat (PM-JAY) eligibility online by visiting the National Health Authority Beneficiary Portal or through offline centers.",
        "snippet_highlighted_words": [
          "online by visiting the National Health Authority Beneficiary Portal or through offline centers"
        ],
        "reference_indexes": [
          0,
          1,
          2
        ]
      },
      {
        "type": "heading",
        "snippet": "Online Eligibility Check Steps"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Go to the Beneficiary NHA Portal or open the official Ayushman App.",
            "reference_indexes": [
              1,
              2,
              3
            ]
          },
          {
            "snippet": "Select the Beneficiary option.",
            "reference_indexes": [
              1,
              4
            ]
          },
          {
            "snippet": "Enter your mobile number and complete the OTP verification.",
            "reference_indexes": [
              1,
              2
            ]
          },
          {
            "snippet": "Select your State/UT, district, and search criteria (such as Aadhaar number, ration card, family ID, or name).",
            "reference_indexes": [
              1,
              5
            ]
          },
          {
            "snippet": "View your family's eligibility status and list of covered members on the screen.",
            "reference_indexes": [
              1,
              4,
              5
            ]
          }
        ]
      },
      {
        "type": "heading",
        "snippet": "Offline Verification Methods"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Common Service Centres (CSCs): Visit your nearest CSC with your Aadhaar card and ration card.",
            "reference_indexes": [
              0,
              6
            ]
          },
          {
            "snippet": "Empanelled Hospitals: Approach the Ayushman Mitra help desk at any PM-JAY empanelled government or private hospital.",
            "reference_indexes": [
              0,
              6
            ]
          },
          {
            "snippet": "Toll-Free Helpline: Call the national helpline numbers 14555 or 1800-111-565 for assistance."
          }
        ],
        "reference_indexes": [
          7,
          8
        ]
      },
      {
        "type": "heading",
        "snippet": "Eligibility Criteria"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "SECC 2011 Database: Economically vulnerable rural and urban households identified from the 2011 Socio-Economic Caste Census data.",
            "reference_indexes": [
              0,
              2
            ]
          },
          {
            "snippet": "Senior Citizens: All citizens aged 70 years and above are eligible regardless of their income under the Ayushman Vaya Vandana scheme."
          }
        ],
        "reference_indexes": [
          2,
          9
        ]
      },
      {
        "type": "paragraph",
        "snippet": "Would you like help finding the nearest empanelled hospital or Common Service Centre in your area?"
      }
    ],
